{
    $empty=['metrics'=>[],'orders'=>[],'daily'=>[],'deposits'=>[],'delivery_cash'=>[],'score'=>null,'score_evidence'=>'No eligible evidence.','deposit_schedule_configured'=>false,'excluded_from_scoring'=>0];
    if($employeeId<=0||!ops_table_exists('ops_orders')||!ops_table_exists('order_payment_allocations')||!ops_table_exists('ops_cash_book_entries'))return $empty;

    $adoption=(string)($settings['bookkeeping_adoption_date']??'2026-07-20');
    if($adoption<'2026-07-20')$adoption='2026-07-20';
    $fromDate=substr($fromSql,0,10);if($fromDate<$adoption)$fromDate=$adoption;
    $fromSql=$fromDate.' 00:00:00';
