    $orders=ops_rows("SELECT o.id,o.order_number,o.customer_name,o.customer_contact,o.payment_method,o.payment_status,o.status,o.total_amount,o.fulfilment_mode,o.order_type,o.completed_at{$shippingColumns},{$displayedAt} loaded_at,p.amount_cents,p.transaction_reference,p.source payment_source,p.updated_at allocation_updated_at FROM ops_orders o JOIN order_payment_allocations p ON p.order_id=o.id AND LOWER(TRIM(p.payment_method))='cash' AND p.amount_cents>0 WHERE LOWER(TRIM(o.status)) IN ('complete','completed') AND o.payment_status IN ('paid','partial') AND {$displayedAt} BETWEEN ? AND ? ORDER BY {$displayedAt},o.id",[$fromSql,$toSql]);

    $eligible=[];$delivery=[];
    foreach($orders as$order){
        $paymentText=strtolower(trim(implode(' ',[(string)$order['payment_method'],(string)$order['transaction_reference'],(string)$order['payment_source']])));
        $modeText=strtolower(trim(preg_replace('/[\s_-]+/',' ',(string)($order['fulfilment_mode']?:$order['order_type']))??''));
        $contactText=strtolower(trim(preg_replace('/[\s_-]+/',' ',(string)$order['customer_contact'])??''));
        $isWalkIn=in_array($contactText,['walk in customer','working customer'],true);
