        $isDeliveryMode=!$isWalkIn&&preg_match('/\b(delivery|driver delivery)\b/',$modeText)===1;
        $isDeliveryWording=preg_match('/\b(cod|cash[ _-]*(on[ _-]*)?delivery|driver[ _-]*(cash|collection|funds?))\b/',$paymentText)===1;
        $isDeliveryCash=$isDeliveryMode||$isDeliveryWording;
