    }

    $entries=ops_rows("SELECT b.*,COALESCE(e.full_name,b.created_by_name,'Unknown employee') created_by_name_resolved FROM ops_cash_book_entries b LEFT JOIN ops_employees e ON e.id=COALESCE(b.created_by_user_id,b.recorded_by) WHERE b.transaction_date BETWEEN DATE_SUB(?,INTERVAL 2 DAY) AND DATE_ADD(?,INTERVAL 2 DAY) AND b.deleted_at IS NULL AND COALESCE(b.status,'active')='active' ORDER BY b.created_at,b.id",[$fromSql,$toSql]);
    $entryNumbers=[];$entriesById=[];$entriesNoNumber=[];
    foreach($entries as$entry){$text=implode(' | ',array_filter([(string)($entry['related_order_number']??''),(string)($entry['description']??''),(string)($entry['notes']??''),(string)($entry['source']??'')]));preg_match_all('/\d{3,}/',$text,$m);$nums=[];foreach($m[0]??[]as$n){$n=(string)(int)$n;if($n!=='0')$nums[$n]=true;}$entry['_reference_text']=$text;$entry['_numbers']=array_keys($nums);if((int)($entry['related_order_id']??0)>0)$entriesById[(int)$entry['related_order_id']][]=$entry;if(count($entry['_numbers'])===1)$entryNumbers[$entry['_numbers'][0]][]=$entry;elseif(!$entry['_numbers']){$key=substr((string)$entry['transaction_date'],0,10).'|'.number_format((float)$entry['cash_in'],2,'.','');$entriesNoNumber[$key][]=$entry;}}
    $orderNumbers=[];$fuzzyOrderCounts=[];
    foreach($eligible as$order){preg_match_all('/\d{3,}/',(string)$order['order_number'],$m);$nums=array_values(array_unique(array_map(static function($v){return(string)(int)$v;},$m[0]??[])));$number=count($nums)===1?$nums[0]:null;if($number!==null)$orderNumbers[$number][]=(int)$order['id'];$key=substr((string)$order['loaded_at'],0,10).'|'.number_format(((int)$order['amount_cents'])/100,2,'.','');$fuzzyOrderCounts[$key]=($fuzzyOrderCounts[$key]??0)+1;}

    $rows=[];
