        else{$key=substr((string)$order['loaded_at'],0,10).'|'.number_format($expected/100,2,'.','');$fuzzy=$entriesNoNumber[$key]??[];if(count($fuzzy)===1&&($fuzzyOrderCounts[$key]??0)===1){$linked=$fuzzy;$method='amount_same_date';$result='fuzzy';}elseif(count($fuzzy)>1||($fuzzyOrderCounts[$key]??0)>1){$linked=$fuzzy;$method='amount_same_date';$result='ambiguous';}}
        $first=$linked[0]??null;$recorded=count($linked)===1?(int)round(((float)$linked[0]['cash_in'])*100):0;if(in_array($result,['matched','fuzzy'],true)&&$recorded!==$expected)$result='amount_mismatch';
        $completed=(string)($order['completed_at']?:$order['loaded_at']);$delay=null;$sameDay=false;$beforeDeadline=false;$backdated=false;if($first&&strtotime($completed)!==false&&strtotime((string)$first['created_at'])!==false){$delay=max(0,(int)floor((strtotime((string)$first['created_at'])-strtotime($completed))/60));$sameDay=substr($completed,0,10)===substr((string)$first['created_at'],0,10);$beforeDeadline=$sameDay&&strtotime((string)$first['created_at'])<=strtotime(substr($completed,0,10).' '.$deadline.':00');$backdated=substr((string)$first['transaction_date'],0,10)<substr((string)$first['created_at'],0,10);}
        $rows[]=['order_id'=>$id,'order_number'=>$order['order_number'],'extracted_order_number'=>$number,'customer_name'=>$order['customer_name'],'loaded_at'=>$order['loaded_at'],'completed_at'=>$completed,'payment_date'=>$completed,'payment_type'=>'Cash','cash_expected'=>$expected/100,'paid'=>'Yes','bookkeeping_entry'=>$first?'BK-'.(int)$first['id']:null,'bookkeeping_entry_id'=>$first['id']??null,'raw_entry_reference'=>$first['_reference_text']??null,'cash_recorded'=>$recorded/100,'recorded_at'=>$first['created_at']??null,'effective_transaction_date'=>$first['transaction_date']??null,'recorded_by'=>$first['created_by_name_resolved']??null,'delay_minutes'=>$delay,'same_day'=>$sameDay,'before_deadline'=>$beforeDeadline,'backdated'=>$backdated,'result'=>$result,'match_method'=>$method,'evidence_source'=>$first?($method.' · ops_cash_book_entries #'.(int)$first['id']):'No matching ledger entry','requires_review'=>in_array($result,['missing','ambiguous','amount_mismatch'],true),'excluded_from_scoring'=>$result==='ambiguous'];}

    $deposits=array_values(array_filter($entries,static function($e){return preg_match('/deposit|banking/i',(string)($e['transaction_type'].' '.$e['source'].' '.$e['description']))===1;}));foreach($deposits as&$d){$d['deposit_amount']=max((float)$d['cash_out'],(float)$d['cash_in']);$d['recorded_at']=$d['created_at'];$d['recorded_by']=$d['created_by_name_resolved'];$d['timing_label']=$depositConfigured?'Recorded against configured deposit schedule':'Evidence only — deposit schedule/retained float not configured';}unset($d);
    $driverFundEntries=array_values(array_filter($entries,static function($e){$description=trim((string)($e['description']??''));$all=(string)($e['transaction_type'].' '.$e['source'].' '.$description.' '.$e['notes']);return(float)$e['cash_in']>0&&(preg_match('/delivery[ _-]*driver|driver[ _-]*(funds?|cash|collection)/i',$all)===1||preg_match('/^[\p{L}][\p{L} .\'’-]{0,60}\s+delivery(?:\s|$)/iu',$description)===1);}));
    $deliveryOutEntries=array_values(array_filter($entries,static function($e){$all=(string)($e['transaction_type'].' '.$e['source'].' '.$e['description'].' '.$e['notes']);return(float)$e['cash_out']>0&&preg_match('/\bdelivery\b|delivery[ _-]*driver|driver[ _-]*(funds?|cash|collection)/i',$all)===1;}));
    $daily=[];foreach($rows as$row){$day=substr((string)$row['completed_at'],0,10);if(!isset($daily[$day]))$daily[$day]=['date'=>$day,'cash_orders'=>0,'expected_cash'=>0.0,'matched_orders'=>0,'recorded_cash'=>0.0,'missing'=>0,'variance'=>0.0,'same_day_entries'=>0,'deposit_expected'=>$depositConfigured?'Configured':'Not configured','deposit_recorded'=>0.0,'deposit_variance'=>null,'result'=>'Reconciled'];$daily[$day]['cash_orders']++;$daily[$day]['expected_cash']+=(float)$row['cash_expected'];$daily[$day]['recorded_cash']+=(float)$row['cash_recorded'];if(in_array($row['result'],['matched','fuzzy'],true))$daily[$day]['matched_orders']++;if($row['result']==='missing')$daily[$day]['missing']++;if($row['same_day'])$daily[$day]['same_day_entries']++;if($row['requires_review'])$daily[$day]['result']='Review';}
    foreach($deposits as$d){$day=substr((string)$d['transaction_date'],0,10);if(isset($daily[$day]))$daily[$day]['deposit_recorded']+=(float)$d['deposit_amount'];}foreach($daily as&$day){$day['variance']=round($day['expected_cash']-$day['recorded_cash'],2);if($depositConfigured)$day['deposit_variance']=round($day['expected_cash']-$day['deposit_recorded'],2);}unset($day);

    $scored=array_values(array_filter($rows,static function($r){return!$r['excluded_from_scoring'];}));$matchedRows=array_values(array_filter($scored,static function($r){return in_array($r['result'],['matched','fuzzy'],true);}));$missingRows=array_values(array_filter($scored,static function($r){return$r['result']==='missing';}));$timed=array_values(array_filter($matchedRows,static function($r){return$r['delay_minutes']!==null;}));$delays=array_column($timed,'delay_minutes');sort($delays,SORT_NUMERIC);$median=$delays?(count($delays)%2?$delays[intdiv(count($delays),2)]:round(($delays[count($delays)/2-1]+$delays[count($delays)/2])/2,1)):null;$sameDay=count(array_filter($timed,static function($r){return$r['before_deadline'];}));$matchRate=$scored?round(100*count($matchedRows)/count($scored),1):null;$sameDayRate=$timed?round(100*$sameDay/count($timed),1):null;$scoreParts=[];if($matchRate!==null)$scoreParts[]=['weight'=>70,'score'=>$matchRate,'label'=>'Cash-order match rate'];if($sameDayRate!==null)$scoreParts[]=['weight'=>30,'score'=>$sameDayRate,'label'=>'Same-day before deadline'];$weight=array_sum(array_column($scoreParts,'weight'));$score=$weight?round(array_sum(array_map(static function($p){return$p['weight']*$p['score'];},$scoreParts))/$weight,1):null;
    $expected=array_sum(array_column($rows,'cash_expected'));$recorded=array_sum(array_column($rows,'cash_recorded'));$moneyIn=array_sum(array_map(static function($e){return(float)$e['cash_in'];},$entries));$moneyOut=array_sum(array_map(static function($e){return(float)$e['cash_out'];},$entries));$deliveryGross=array_sum(array_map(static function($o){return((int)$o['amount_cents'])/100;},$delivery));$deliveryFees=array_sum(array_map(static function($o){return max(0,(float)($o['shipping_total']??0)+(float)($o['shipping_tax_total']??0));},$delivery));$deliveryExpected=max(0,$deliveryGross-$deliveryFees);$driverFundsRecorded=array_sum(array_map(static function($e){return(float)$e['cash_in'];},$driverFundEntries));$deliveryOut=array_sum(array_map(static function($e){return(float)$e['cash_out'];},$deliveryOutEntries));$depositAmount=array_sum(array_map(static function($e){return(float)$e['deposit_amount'];},$deposits));$oldest=$missingRows?$missingRows[0]:null;foreach($missingRows as$r)if((string)$r['completed_at']<(string)$oldest['completed_at'])$oldest=$r;
    $metrics=[['label'=>'Counter / Collection Cash Expected','value'=>count($rows),'explanation'=>'Completed paid cash orders expected in ordinary bookkeeping: walk-ins and customer collections. Cash deliveries are measured separately as Delivery Driver Funds.'],['label'=>'Cash Orders Matched','value'=>count($matchedRows),'explanation'=>'Expected counter or collection cash orders with one reliable matching bookkeeping entry.'],['label'=>'Match Rate','value'=>$matchRate,'format'=>'percent','explanation'=>'Matched eligible counter/collection cash orders divided by all eligible non-ambiguous cash orders.'],['label'=>'Cash Orders Missing','value'=>count($missingRows),'explanation'=>'Eligible walk-in or collection cash orders with no matching ordinary bookkeeping entry. Delivery cash is excluded from this figure.'],['label'=>'Missing Cash Value','value'=>array_sum(array_column($missingRows,'cash_expected')),'format'=>'currency'],['label'=>'Cash Amount Expected','value'=>$expected,'format'=>'currency'],['label'=>'Cash Amount Recorded','value'=>$recorded,'format'=>'currency'],['label'=>'Cash Variance','value'=>$expected-$recorded,'format'=>'currency','explanation'=>'Eligible counter/collection cash expected minus the amount recorded against those orders. Delivery Driver Funds do not inflate this variance.'],['label'=>'Delivery Cash Orders','value'=>count($delivery),'status'=>'reference','explanation'=>'Cash delivery orders reconciled separately from counter cash.'],['label'=>'Gross Delivery Cash','value'=>$deliveryGross,'format'=>'currency','status'=>'reference'],['label'=>'Driver Delivery Fees','value'=>$deliveryFees,'format'=>'currency','status'=>'reference','explanation'=>'Shipping and shipping-tax amounts belonging to the delivery service/driver.'],['label'=>'Expected Delivery Cash','value'=>$deliveryExpected,'format'=>'currency','status'=>'reference','explanation'=>'Gross cash collected on delivery orders minus the delivery fee belonging to the driver.'],['label'=>'Delivery Driver Funds Recorded','value'=>$driverFundsRecorded,'format'=>'currency','status'=>'reference','explanation'=>'Cash-in entries explicitly labelled for a driver, including names followed by “delivery”, such as “AJ delivery” or “Leo delivery”.'],['label'=>'Delivery Funds Difference','value'=>$deliveryExpected-$driverFundsRecorded,'format'=>'currency','status'=>'reference','explanation'=>'Net delivery cash expected minus Delivery Driver Funds recorded. This is a review figure, not an employee score, because driver remittances may combine several orders or cross dates.'],['label'=>'Same-Day Logging Compliance','value'=>$sameDayRate,'format'=>'percent'],['label'=>'Average Logging Delay','value'=>$delays?round(array_sum($delays)/count($delays),1):null,'format'=>'minutes'],['label'=>'Median Logging Delay','value'=>$median,'format'=>'minutes'],['label'=>'Duplicate / Ambiguous / Mismatched','value'=>count(array_filter($rows,static function($r){return in_array($r['result'],['ambiguous','amount_mismatch'],true);}))],['label'=>'Deposits Recorded Amount','value'=>$depositAmount,'format'=>'currency','explanation'=>'Total amount of active bookkeeping entries identified as deposits or banking for the selected period.'],['label'=>'Deposit Entries','value'=>count($deposits)],['label'=>'Money In','value'=>$moneyIn,'format'=>'currency'],['label'=>'Money Out','value'=>$moneyOut,'format'=>'currency','explanation'=>'All active bookkeeping cash-out entries in the selected period. See the breakdown below for delivery-related money out.'],['label'=>'Delivery Out','value'=>$deliveryOut,'format'=>'currency','explanation'=>'Cash-out entries containing “delivery”; normally money paid to or allocated for delivery services.']];
    return['metrics'=>$metrics,'orders'=>$rows,'daily'=>array_values($daily),'deposits'=>$deposits,'money_out_entries'=>array_map(static function($e){return['transaction_date'=>$e['transaction_date'],'description'=>$e['description'],'cash_out'=>(float)$e['cash_out'],'source'=>$e['source'],'notes'=>$e['notes'],'recorded_by'=>$e['created_by_name_resolved'],'created_at'=>$e['created_at'],'category'=>preg_match('/\bdelivery\b/i',(string)($e['transaction_type'].' '.$e['source'].' '.$e['description'].' '.$e['notes']))===1?'Delivery out':'Other money out'];},array_values(array_filter($entries,static function($e){return(float)$e['cash_out']>0;}))),'delivery_cash'=>array_map(static function($o){$gross=((int)$o['amount_cents'])/100;$fee=max(0,(float)($o['shipping_total']??0)+(float)($o['shipping_tax_total']??0));return['order_id'=>(int)$o['id'],'order_number'=>$o['order_number'],'loaded_at'=>$o['loaded_at'],'gross_amount'=>$gross,'driver_delivery_fee'=>$fee,'amount'=>max(0,$gross-$fee),'payment_type_detail'=>$o['payment_type_detail'],'fulfilment_mode'=>$o['fulfilment_mode_detail'],'reason'=>'Cash delivery is reconciled against Delivery Driver Funds after subtracting the driver delivery fee'];},$delivery),'score'=>$score,'score_components'=>$scoreParts,'score_evidence'=>count($matchedRows).' of '.count($scored).' eligible completed counter/collection cash orders reconciled; '.$sameDay.' of '.count($timed).' timed matches logged by '.$deadline.'. Delivery cash is reported separately.','deposit_schedule_configured'=>$depositConfigured,'deposit_schedule'=>$depositSchedule?:null,'cash_deadline'=>$deadline,'adoption_date'=>$adoption,'period_from'=>$fromDate,'excluded_from_scoring'=>count(array_filter($rows,static function($r){return$r['excluded_from_scoring'];})),'matching_method'=>'Numeric order number first; linked order ID second; amount + same completion date only when unique','summary'=>['eligible_orders'=>count($rows),'matched'=>count($matchedRows),'fuzzy'=>count(array_filter($rows,static function($r){return$r['result']==='fuzzy';})),'missing'=>count($missingRows),'ambiguous'=>count(array_filter($rows,static function($r){return$r['result']==='ambiguous';})),'amount_mismatch'=>count(array_filter($rows,static function($r){return$r['result']==='amount_mismatch';})),'expected_cash'=>$expected,'recorded_cash'=>$recorded,'variance'=>$expected-$recorded,'oldest_missing'=>$oldest,'same_day_count'=>$sameDay,'timed_count'=>count($timed),'average_delay_minutes'=>$delays?round(array_sum($delays)/count($delays),1):null,'median_delay_minutes'=>$median,'fastest_delay_minutes'=>$delays?$delays[0]:null,'slowest_delay_minutes'=>$delays?$delays[count($delays)-1]:null,'delivery_cash_excluded'=>count($delivery),'delivery_cash_gross'=>$deliveryGross,'delivery_driver_fees'=>$deliveryFees,'delivery_cash_expected'=>$deliveryExpected,'delivery_driver_funds_recorded'=>$driverFundsRecorded,'delivery_funds_difference'=>$deliveryExpected-$driverFundsRecorded,'deposit_amount'=>$depositAmount,'delivery_out'=>$deliveryOut,'money_in'=>$moneyIn,'money_out'=>$moneyOut]];
